parts.modelAnswer:
Arquitectura. El patrón MVC separa la aplicación en Modelo (datos y reglas de negocio), Vista (presentación) y Controlador (recibe la petición, invoca al modelo y elige la respuesta). En una API REST la vista es la respuesta serializada (JSON con DTO); en una web con Razor sería la plantilla. Lo organizo en capas con dependencias en un solo sentido: presentación (endpoints o controladores, solo traducen HTTP a llamadas y devuelven DTO) -> lógica de aplicación y dominio (reglas, p. ej. el método Resolve de la solicitud) -> acceso a datos (DbContext de EF Core). Las entidades de EF Core no se exponen en la API: se devuelven DTO, para no acoplar el contrato público a la base de datos ni filtrar campos internos.

Entidades:

public enum ApplicationStatus { Submitted, UnderReview, Granted, Rejected }

public class Municipality
{
    public int Id { get; set; }
    public string IneCode { get; set; } = "";
    public string Name { get; set; } = "";
    public string ContactEmail { get; set; } = "";
    public List<GrantApplication> Applications { get; } = [];
}

public class GrantCall
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Name { get; set; } = "";
    public int Year { get; set; }
    public List<GrantApplication> Applications { get; } = [];
}

public class GrantApplication
{
    public int Id { get; set; }
    public int MunicipalityId { get; set; }
    public Municipality Municipality { get; set; } = null!;
    public int GrantCallId { get; set; }
    public GrantCall GrantCall { get; set; } = null!;
    public decimal RequestedAmount { get; set; }
    public DateOnly SubmittedOn { get; set; }
    public ApplicationStatus Status { get; set; }
    public decimal? GrantedAmount { get; set; }
    public DateOnly? ResolvedOn { get; set; }
}

Un ayuntamiento y una convocatoria tienen muchas solicitudes (1:N); las claves ajenas (MunicipalityId, GrantCallId) están en GrantApplication. El importe concedido y la fecha de resolución son nullable porque solo se rellenan al resolver.

Contexto de datos:

public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Municipality> Municipalities => Set<Municipality>();
    public DbSet<GrantCall> GrantCalls => Set<GrantCall>();
    public DbSet<GrantApplication> Applications => Set<GrantApplication>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Municipality>(e =>
        {
            e.Property(m => m.IneCode).HasMaxLength(5).IsFixedLength();
            e.Property(m => m.Name).HasMaxLength(200);
            e.HasIndex(m => m.IneCode).IsUnique();
        });

        modelBuilder.Entity<GrantCall>(e =>
        {
            e.Property(c => c.Code).HasMaxLength(30);
            e.HasIndex(c => c.Code).IsUnique();
        });

        modelBuilder.Entity<GrantApplication>(e =>
        {
            e.Property(a => a.RequestedAmount).HasPrecision(12, 2);
            e.Property(a => a.GrantedAmount).HasPrecision(12, 2);
            e.Property(a => a.Status).HasConversion<string>().HasMaxLength(20);
            e.HasOne(a => a.Municipality).WithMany(m => m.Applications).HasForeignKey(a => a.MunicipalityId);
            e.HasOne(a => a.GrantCall).WithMany(c => c.Applications).HasForeignKey(a => a.GrantCallId);
            e.ToTable(t => t.HasCheckConstraint("ck_applications_granted_amount",
                "\"GrantedAmount\" IS NULL OR (\"GrantedAmount\" >= 0 AND \"GrantedAmount\" <= \"RequestedAmount\")"));
        });
    }
}

Los importes llevan precisión decimal (no float), el estado se guarda como texto legible y el código INE es único. Después se genera la migración con dotnet ef migrations add.

Registro de ProblemDetails y del endpoint (Program.cs):

builder.Services.AddProblemDetails();
builder.Services.AddSingleton(TimeProvider.System);
// ...
app.UseExceptionHandler();
app.UseStatusCodePages();

public sealed record ResolveApplicationRequest(string Status, decimal? GrantedAmount);

app.MapPost("/api/v1/applications/{id:int}/resolution", async (
    int id, ResolveApplicationRequest request, AppDbContext db, TimeProvider time, CancellationToken ct) =>
{
    var application = await db.Applications.FirstOrDefaultAsync(a => a.Id == id, ct);
    if (application is null)
    {
        return Results.Problem(
            title: "Solicitud no encontrada",
            detail: $"No existe la solicitud {id}.",
            statusCode: StatusCodes.Status404NotFound);
    }

    if (application.Status != ApplicationStatus.UnderReview)
    {
        return Results.Problem(
            title: "Estado no válido",
            detail: "Solo se puede resolver una solicitud que está en revisión.",
            statusCode: StatusCodes.Status409Conflict);
    }

    var errors = new Dictionary<string, string[]>();
    if (!Enum.TryParse<ApplicationStatus>(request.Status, ignoreCase: true, out var finalStatus)
        || finalStatus is not (ApplicationStatus.Granted or ApplicationStatus.Rejected))
    {
        errors["status"] = ["El estado final debe ser Granted o Rejected."];
    }
    else if (finalStatus == ApplicationStatus.Granted
        && (request.GrantedAmount is null or <= 0 || request.GrantedAmount > application.RequestedAmount))
    {
        errors["grantedAmount"] = ["El importe concedido debe ser mayor que 0 y no superar el solicitado."];
    }

    if (errors.Count > 0)
    {
        return Results.ValidationProblem(errors);
    }

    application.Resolve(finalStatus, request.GrantedAmount, DateOnly.FromDateTime(time.GetUtcNow().UtcDateTime));
    await db.SaveChangesAsync(ct);
    return Results.NoContent();
});

El cambio de estado lo hace un método de la entidad, no el endpoint, para que la regla viva en el dominio:

public void Resolve(ApplicationStatus finalStatus, decimal? grantedAmount, DateOnly today)
{
    Status = finalStatus;
    GrantedAmount = finalStatus == ApplicationStatus.Granted ? grantedAmount : null;
    ResolvedOn = today;
}

Códigos: 404 si no existe, 409 si no está en revisión, 400 (ValidationProblem, con los errores por campo) si el estado final o el importe no son válidos, 204 si todo va bien. Todos los errores salen como application/problem+json (ProblemDetails, RFC 9457, que sustituye a la RFC 7807); AddProblemDetails, UseExceptionHandler y UseStatusCodePages hacen que también lo sean las excepciones no controladas y los códigos de estado sin cuerpo.

Pruebas: unitarias de GrantApplication.Resolve (concedida: guarda importe y fecha; denegada: sin importe) con un TimeProvider falso para fijar la fecha; e integración con WebApplicationFactory y una base de datos de pruebas: resolución correcta como Granted y como Rejected (204), solicitud inexistente (404), solicitud que no está en revisión (409), estado final desconocido (400), importe nulo, cero, negativo o superior al solicitado (400) y una segunda resolución de la misma solicitud (409).
